            "code": "import React, { useState } from 'react';\n\ninterface ChatInputWithActionsProps {\n  onSendMessage: (message: string) => void;\n}\n\nexport function ChatInputWithActions({ onSendMessage }: ChatInputWithActionsProps) {\n  const [input, setInput] = useState('');\n\n  const handleSubmit = (e: React.FormEvent) => {\n    e.preventDefault();\n    if (input.trim()) {\n      onSendMessage(input);\n      setInput('');\n    }\n  };\n\n  return (\n    <form onSubmit={handleSubmit} className=\"flex gap-2\">\n      <input\n        type=\"text\"\n        value={input}\n        onChange={(e) => setInput(e.target.value)}\n        placeholder=\"Type a message...\"\n        className=\"flex-1 bg-background-700 border border-background-600 rounded px-3 py-2 text-sm text-foreground-50 placeholder-foreground-400 focus:outline-none focus:border-accent-500\"\n      />\n      <button\n        type=\"submit\"\n        className=\"px-4 py-2 bg-accent-500 text-foreground-50 rounded font-medium hover:bg-accent-600 transition-colors text-sm\"\n      >\n        Send\n      </button>\n    </form>\n  );\n}\n",
