    "code": "import { Badge } from 'ui-lab-components'\n\nfunction BadgeRow({ tags }) {\n  return (\n    <div className=\"flex flex-wrap gap-1.5\">\n      {tags.map((tag) => (\n        <Badge key={tag} size=\"sm\">{tag}</Badge>\n      ))}\n    </div>\n  )\n}",
